class BugType {
private:
  using CheckerNameInfo = std::variant<CheckerNameRef, const CheckerFrontend *>;

  const CheckerNameInfo CheckerName;
  const std::string Description;
  const std::string Category;
  bool SuppressOnSink;

  virtual void anchor();

public:
  // Straightforward constructor where the checker name is specified directly.
  // TODO: As far as I know all applications of this constructor involve ugly
  // hacks that could be avoided by switching to the other constructor.
  // When those are all eliminated, this constructor should be removed to
  // eliminate the `variant` and simplify this class.
  BugType(CheckerNameRef CheckerName, StringRef Desc,
          StringRef Cat = categories::LogicError, bool SuppressOnSink = false)
      : CheckerName(CheckerName), Description(Desc), Category(Cat),
        SuppressOnSink(SuppressOnSink) {}
  // Constructor that can be called from the constructor of a checker object.
  // At that point the checker name is not yet available, but we can save a
  // pointer to the checker and use that to query the name.
  BugType(const CheckerFrontend *Checker, StringRef Desc,
          StringRef Cat = categories::LogicError, bool SuppressOnSink = false)
      : CheckerName(Checker), Description(Desc), Category(Cat),
        SuppressOnSink(SuppressOnSink) {}
  virtual ~BugType() = default;

  StringRef getDescription() const { return Description; }
  StringRef getCategory() const { return Category; }
  StringRef getCheckerName() const {
    if (const auto *CNR = std::get_if<CheckerNameRef>(&CheckerName))
      return *CNR;

    return std::get<const CheckerFrontend *>(CheckerName)->getName();
  }

  /// isSuppressOnSink - Returns true if bug reports associated with this bug
  ///  type should be suppressed if the end node of the report is post-dominated
  ///  by a sink node.
  bool isSuppressOnSink() const { return SuppressOnSink; }
}

class CXXAllocatorCall : public AnyFunctionCall {
  friend class CallEventManager;

protected:
  CXXAllocatorCall(const CXXNewExpr *E, ProgramStateRef St,
                   const StackFrame *SF, CFGBlock::ConstCFGElementRef ElemRef)
      : AnyFunctionCall(E, St, SF, ElemRef) {}
  CXXAllocatorCall(const CXXAllocatorCall &Other) = default;

  void cloneTo(void *Dest) const override {
    new (Dest) CXXAllocatorCall(*this);
  }

public:
  const CXXNewExpr *getOriginExpr() const override {
    return cast<CXXNewExpr>(AnyFunctionCall::getOriginExpr());
  }

  const FunctionDecl *getDecl() const override {
    return getOriginExpr()->getOperatorNew();
  }

  SVal getObjectUnderConstruction() const {
    return *ExprEngine::getObjectUnderConstruction(getState(), getOriginExpr(),
                                                   getStackFrame());
  }

  /// Number of non-placement arguments to the call. It is equal to 2 for
  /// C++17 aligned operator new() calls that have alignment implicitly
  /// passed as the second argument, and to 1 for other operator new() calls.
  unsigned getNumImplicitArgs() const {
    return getOriginExpr()->getNumImplicitArgs();
  }

  unsigned getNumArgs() const override {
    return getOriginExpr()->getNumPlacementArgs() + getNumImplicitArgs();
  }

  bool isArray() const { return getOriginExpr()->isArray(); }

  std::optional<const clang::Expr *> getArraySizeExpr() const {
    return getOriginExpr()->getArraySize();
  }

  SVal getArraySizeVal() const {
    assert(isArray() && "The allocator call doesn't allocate and array!");

    return getState()->getSVal(*getArraySizeExpr(), getStackFrame());
  }

  const Expr *getArgExpr(unsigned Index) const override {
    // The first argument of an allocator call is the size of the allocation.
    if (Index < getNumImplicitArgs())
      return nullptr;
    return getOriginExpr()->getPlacementArg(Index - getNumImplicitArgs());
  }

  /// Number of placement arguments to the operator new() call. For example,
  /// standard std::nothrow operator new and standard placement new both have
  /// 1 implicit argument (size) and 1 placement argument, while regular
  /// operator new() has 1 implicit argument and 0 placement arguments.
  const Expr *getPlacementArgExpr(unsigned Index) const {
    return getOriginExpr()->getPlacementArg(Index);
  }

  Kind getKind() const override { return CE_CXXAllocator; }
  StringRef getKindAsString() const override { return "CXXAllocatorCall"; }

  static bool classof(const CallEvent *CE) {
    return CE->getKind() == CE_CXXAllocator;
  }
}

