};

class ExplodedGraph {
protected:
  friend class CoreEngine;

  // Type definitions.
  using NodeVector = std::vector<ExplodedNode *>;

  /// The root of the simulation graph. Can be nullptr if the graph is empty or
  /// if it was populated by `createUncachedNode()`.
  ExplodedNode *Root = nullptr;

  /// The nodes in the simulation graph which have been
  /// specially marked as the endpoint of an abstract simulation path.
  NodeVector EndNodes;

  /// Nodes - The nodes in the graph.
  llvm::FoldingSet<ExplodedNode> Nodes;

  /// BVC - Allocator and context for allocating nodes and their predecessor
  /// and successor groups.
  BumpVectorContext BVC;

  /// NumNodes - The number of nodes in the graph.
  int64_t NumNodes = 0;

  /// A list of recently allocated nodes that can potentially be recycled.
  NodeVector ChangedNodes;

  /// A list of nodes that can be reused.
  NodeVector FreeNodes;

  /// Determines how often nodes are reclaimed.
  ///
  /// If this is 0, nodes will never be reclaimed.
  unsigned ReclaimNodeInterval = 0;

  /// Counter to determine when to reclaim nodes.
  unsigned ReclaimCounter;

public:
  ExplodedGraph();
  ~ExplodedGraph();

  /// Get the root node of the graph. This may return nullptr if the graph is
  /// empty or under construction.
  ExplodedNode *getRoot() const { return Root; }

  /// Retrieve the node associated with a (Location, State) pair, where the
  /// 'Location' is a ProgramPoint in the CFG. If no node for this pair exists,
  /// it is created. IsNew is set to true if the node was freshly created.
  ExplodedNode *getNode(const ProgramPoint &L, ProgramStateRef State,
                        bool IsSink = false,
                        bool* IsNew = nullptr);

  /// Create a node for a (Location, State) pair, but don't store it for
  /// deduplication later. This is useful when copying some nodes from an
  /// already completed ExplodedGraph for further processing.
  ExplodedNode *createUncachedNode(const ProgramPoint &L,
    ProgramStateRef State,
    int64_t Id,
    bool IsSink = false);

  /// Mark a node as the root of the graph. Calling this is an error if the
  /// graph already has a root node.
  void designateAsRoot(ExplodedNode *V) {
    assert(V && "Cannot designate nullptr as root!");
    assert(!Root && "The graph already has a root, cannot designate another!");
    Root = V;
  }

  /// addEndOfPath - Add an untyped node to the set of EOP nodes.
  ExplodedNode *addEndOfPath(ExplodedNode *V) {
    EndNodes.push_back(V);
    return V;
  }

  unsigned num_eops() const { return EndNodes.size(); }

  bool empty() const { return NumNodes == 0; }
  unsigned size() const { return NumNodes; }

  void reserve(unsigned NodeCount) { Nodes.reserve(NodeCount); }

  // Iterators.
  using NodeTy = ExplodedNode;
  using AllNodesTy = llvm::FoldingSet<ExplodedNode>;
  using eop_iterator = NodeVector::iterator;
  using const_eop_iterator = NodeVector::const_iterator;
  using node_iterator = AllNodesTy::iterator;
  using const_node_iterator = AllNodesTy::const_iterator;

  llvm::iterator_range<node_iterator> nodes() { return Nodes; }

  llvm::iterator_range<const_node_iterator> nodes() const { return Nodes; }

  eop_iterator eop_begin() { return EndNodes.begin(); }

  eop_iterator eop_end() { return EndNodes.end(); }

  const_eop_iterator eop_begin() const { return EndNodes.begin(); }

  const_eop_iterator eop_end() const { return EndNodes.end(); }

  llvm::BumpPtrAllocator & getAllocator() { return BVC.getAllocator(); }
  BumpVectorContext &getNodeAllocator() { return BVC; }

  using NodeMap = llvm::DenseMap<const ExplodedNode *, ExplodedNode *>;

  /// Creates a trimmed version of the graph that only contains paths leading
  /// to the given nodes.
  ///
  /// \param Nodes The nodes which must appear in the final graph. Presumably
  ///              these are end-of-path nodes (i.e. they have no successors).
  /// \param[out] ForwardMap An optional map from nodes in this graph to nodes
  ///                        in the returned graph.
  /// \param[out] InverseMap An optional map from nodes in the returned graph to
  ///                        nodes in this graph.
  /// \returns The trimmed graph
  std::unique_ptr<ExplodedGraph>
  trim(ArrayRef<const NodeTy *> Nodes,
       InterExplodedGraphMap *ForwardMap = nullptr,
       InterExplodedGraphMap *InverseMap = nullptr) const;

  /// Enable tracking of recently allocated nodes for potential reclamation
  /// when calling reclaimRecentlyAllocatedNodes().
  void enableNodeReclamation(unsigned Interval) {
    ReclaimCounter = ReclaimNodeInterval = Interval;
  }

  /// Reclaim "uninteresting" nodes created since the last time this method
  /// was called.
  void reclaimRecentlyAllocatedNodes();

  /// Returns true if nodes for the given expression kind are always
  ///        kept around.
  static bool isInterestingLValueExpr(const Expr *Ex);

private:
  bool shouldCollect(const ExplodedNode *node);
  void collectNode(ExplodedNode *node);
}

class ExplodedNode : public llvm::FoldingSetNode {
  friend class CoreEngine;
  friend class ExplodedGraph;
  friend class NodeBuilder;

  /// Efficiently stores a list of ExplodedNodes, or an optional flag.
  ///
  /// NodeGroup provides opaque storage for a list of ExplodedNodes, optimizing
  /// for the case when there is only one node in the group. This is a fairly
  /// common case in an ExplodedGraph, where most nodes have only one
  /// predecessor and many have only one successor. It can also be used to
  /// store a flag rather than a node list, which ExplodedNode uses to mark
  /// whether a node is a sink. If the flag is set, the group is implicitly
  /// empty and no nodes may be added.
  class NodeGroup {
    // Conceptually a discriminated union. If the low bit is set, the node is
    // a sink. If the low bit is not set, the pointer refers to the storage
    // for the nodes in the group.
    // This is not a PointerIntPair in order to keep the storage type opaque.
    uintptr_t P;

  public:
    NodeGroup(bool Flag = false) : P(Flag) {
      assert(getFlag() == Flag);
    }

    ExplodedNode * const *begin() const;

    ExplodedNode * const *end() const;

    unsigned size() const;

    bool empty() const { return P == 0 || getFlag() != 0; }

    /// Adds a node to the list.
    ///
    /// The group must not have been created with its flag set.
    void addNode(ExplodedNode *N, ExplodedGraph &G);

    /// Replaces the single node in this group with a new node.
    ///
    /// Note that this should only be used when you know the group was not
    /// created with its flag set, and that the group is empty or contains
    /// only a single node.
    void replaceNode(ExplodedNode *node);

    /// Returns whether this group was created with its flag set.
    bool getFlag() const {
      return (P & 1);
    }
  };

  /// Location - The program location (within a function body) associated
  ///  with this node.
  const ProgramPoint Location;

  /// State - The state associated with this node.
  ProgramStateRef State;

  /// Preds - The predecessors of this node.
  NodeGroup Preds;

  /// Succs - The successors of this node.
  NodeGroup Succs;

  int64_t Id;

public:
  explicit ExplodedNode(const ProgramPoint &loc, ProgramStateRef state,
                        int64_t Id, bool IsSink)
      : Location(loc), State(std::move(state)), Succs(IsSink), Id(Id) {
    assert(isSink() == IsSink);
  }

  /// getLocation - Returns the edge associated with the given node.
  ProgramPoint getLocation() const { return Location; }

  const StackFrame *getStackFrame() const {
    return getLocation().getStackFrame();
  }

  /// Iterates over the current stack frame and all of its ancestors.
  llvm::iterator_range<StackFrame::parent_iterator> stackframes() const {
    return getStackFrame()->parentsIncludingSelf();
  }

  const Decl &getCodeDecl() const { return *getStackFrame()->getDecl(); }

  CFG &getCFG() const { return *getStackFrame()->getCFG(); }

  const CFGBlock *getCFGBlock() const;

  const ParentMap &getParentMap() const {
    return getStackFrame()->getParentMap();
  }

  template <typename T> T &getAnalysis() const {
    return *getStackFrame()->getAnalysis<T>();
  }

  const ProgramStateRef &getState() const { return State; }

  template <typename T> std::optional<T> getLocationAs() const & {
    return Location.getAs<T>();
  }

  /// Get the value of an arbitrary expression at this node.
  SVal getSVal(const Expr *E) const {
    return getState()->getSVal(E, getStackFrame());
  }

  static void Profile(llvm::FoldingSetNodeID &ID,
                      const ProgramPoint &Loc,
                      const ProgramStateRef &state,
                      bool IsSink) {
    ID.Add(Loc);
    ID.AddPointer(state.get());
    ID.AddBoolean(IsSink);
  }

  void Profile(llvm::FoldingSetNodeID& ID) const {
    // We avoid copy constructors by not using accessors.
    Profile(ID, Location, State, isSink());
  }

  /// addPredeccessor - Adds a predecessor to the current node, and
  ///  in tandem add this node as a successor of the other node.
  void addPredecessor(ExplodedNode *V, ExplodedGraph &G);

  unsigned succ_size() const { return Succs.size(); }
  unsigned pred_size() const { return Preds.size(); }
  bool succ_empty() const { return Succs.empty(); }
  bool pred_empty() const { return Preds.empty(); }

  bool isSink() const { return Succs.getFlag(); }

  bool hasSinglePred() const {
    return (pred_size() == 1);
  }

  ExplodedNode *getFirstPred() {
    return pred_empty() ? nullptr : *(pred_begin());
  }

  const ExplodedNode *getFirstPred() const {
    return const_cast<ExplodedNode*>(this)->getFirstPred();
  }

  ExplodedNode *getFirstSucc() {
    return succ_empty() ? nullptr : *(succ_begin());
  }

  const ExplodedNode *getFirstSucc() const {
    return const_cast<ExplodedNode*>(this)->getFirstSucc();
  }

  // Iterators over successor and predecessor vertices.
  using succ_iterator = ExplodedNode * const *;
  using succ_range = llvm::iterator_range<succ_iterator>;

  using const_succ_iterator = const ExplodedNode * const *;
  using const_succ_range = llvm::iterator_range<const_succ_iterator>;

  using pred_iterator = ExplodedNode * const *;
  using pred_range = llvm::iterator_range<pred_iterator>;

  using const_pred_iterator = const ExplodedNode * const *;
  using const_pred_range = llvm::iterator_range<const_pred_iterator>;

  pred_iterator pred_begin() { return Preds.begin(); }
  pred_iterator pred_end() { return Preds.end(); }
  pred_range preds() { return {Preds.begin(), Preds.end()}; }

  const_pred_iterator pred_begin() const {
    return const_cast<ExplodedNode*>(this)->pred_begin();
  }
  const_pred_iterator pred_end() const {
    return const_cast<ExplodedNode*>(this)->pred_end();
  }
  const_pred_range preds() const { return {Preds.begin(), Preds.end()}; }

  succ_iterator succ_begin() { return Succs.begin(); }
  succ_iterator succ_end() { return Succs.end(); }
  succ_range succs() { return {Succs.begin(), Succs.end()}; }

  const_succ_iterator succ_begin() const {
    return const_cast<ExplodedNode*>(this)->succ_begin();
  }
  const_succ_iterator succ_end() const {
    return const_cast<ExplodedNode*>(this)->succ_end();
  }
  const_succ_range succs() const { return {Succs.begin(), Succs.end()}; }

  int64_t getID() const { return Id; }

  /// The node is trivial if it has only one successor, only one predecessor,
  /// it's predecessor has only one successor,
  /// and its program state is the same as the program state of the previous
  /// node.
  /// Trivial nodes may be skipped while printing exploded graph.
  bool isTrivial() const;

  /// If the node's program point corresponds to a statement, retrieve that
  /// statement. Useful for figuring out where to put a warning or a note.
  /// If the statement belongs to a body-farmed definition,
  /// retrieve the call site for that definition.
  const Stmt *getStmtForDiagnostics() const;

  /// Find the next statement that was executed on this node's execution path.
  /// Useful for explaining control flow that follows the current node.
  /// If the statement belongs to a body-farmed definition, retrieve the
  /// call site for that definition.
  const Stmt *getNextStmtForDiagnostics() const;

  /// Find the statement that was executed immediately before this node.
  /// Useful when the node corresponds to a CFG block entrance.
  /// If the statement belongs to a body-farmed definition, retrieve the
  /// call site for that definition.
  const Stmt *getPreviousStmtForDiagnostics() const;

  /// Find the statement that was executed at or immediately before this node.
  /// Useful when any nearby statement will do.
  /// If the statement belongs to a body-farmed definition, retrieve the
  /// call site for that definition.
  const Stmt *getCurrentOrPreviousStmtForDiagnostics() const;

private:
  void replaceSuccessor(ExplodedNode *node) { Succs.replaceNode(node); }
  void replacePredecessor(ExplodedNode *node) { Preds.replaceNode(node); }
}

class ExplodedNodeSet {
  using ImplTy = llvm::SmallSetVector<ExplodedNode *, 4>;
  ImplTy Impl;

public:
  ExplodedNodeSet(ExplodedNode *N) { insert(N); }

  ExplodedNodeSet() = default;

  using iterator = ImplTy::iterator;
  using const_iterator = ImplTy::const_iterator;

  unsigned size() const { return Impl.size();  }
  bool empty()    const { return Impl.empty(); }
  bool erase(ExplodedNode *N) { return Impl.remove(N); }

  void clear() { Impl.clear(); }

  void insert(ExplodedNode *N) {
    if (N && !N->isSink())
      Impl.insert(N);
  }

  void insert(const ExplodedNodeSet &S) {
    if (&S == this)
      return;
    if (empty())
      Impl = S.Impl;
    else
      Impl.insert_range(S);
  }

  iterator begin() { return Impl.begin(); }
  iterator end() { return Impl.end(); }

  const_iterator begin() const { return Impl.begin(); }
  const_iterator end() const { return Impl.end(); }
}

class ExprEngine {
  void anchor();

public:
  /// The modes of inlining, which override the default analysis-wide settings.
  enum InliningModes {
    /// Follow the default settings for inlining callees.
    Inline_Regular = 0,

    /// Do minimal inlining of callees.
    Inline_Minimal = 0x1
  };

private:
  cross_tu::CrossTranslationUnitContext &CTU;
  bool IsCTUEnabled;

  AnalysisManager &AMgr;

  AnalysisDeclContextManager &AnalysisDeclContexts;

  CoreEngine Engine;

  /// G - the simulation graph.
  ExplodedGraph &G;

  /// StateMgr - Object that manages the data for all created states.
  ProgramStateManager StateMgr;

  /// SymMgr - Object that manages the symbol information.
  SymbolManager &SymMgr;

  /// MRMgr - MemRegionManager object that creates memory regions.
  MemRegionManager &MRMgr;

  /// svalBuilder - SValBuilder object that creates SVals from expressions.
  SValBuilder &svalBuilder;

  unsigned int currStmtIdx = 0;

  /// Pointer to a (so-called, somewhat misnamed) NodeBuilderContext object
  /// which has three independent roles:
  /// - It holds a pointer to the CFGBlock that is currently under analysis.
  ///   (This is the primary way to get the current block.)
  /// - It holds a pointer to the current StackFrame. (This is rarely
  ///   used, the stack frame is usually queried from a recent
  ///   ExplodedNode. Unfortunately it seems that these two sources of truth
  ///   are not always consistent.)
  /// - It can be used for constructing `NodeBuilder`s. Practically all
  ///   `NodeBuilder` objects are useless complications in the code, so I
  ///   intend to replace them with direct use of `CoreEngine::makeNode`.
  /// TODO: Eventually `currBldrCtx` should be replaced by two separate fields:
  /// `const CFGBlock *CurrBlock` & `const StackFrame *CurrStackFrame`
  /// that are kept up-to-date and are almost always non-null during the
  /// analysis. I will switch to this more natural representation when
  /// `NodeBuilder`s are eliminated from the code.
  const NodeBuilderContext *currBldrCtx = nullptr;
  /// Historically `currBldrCtx` pointed to a local variable in some stack
  /// frame. This field is introduced as a temporary measure to allow a gradual
  /// transition. Only use this in {re,}setCurrStackFrameAndBlock!
  /// TODO: Remove this temporary hack.
  std::optional<NodeBuilderContext> OwnedCurrBldrCtx;

  /// Helper object to determine if an Objective-C message expression
  /// implicitly never returns.
  ObjCNoReturn ObjCNoRet;

  /// The BugReporter associated with this engine. It is important that
  /// this object be placed at the very end of member variables so that its
  /// destructor is called before the rest of the ExprEngine is destroyed.
  PathSensitiveBugReporter BR;

  /// The functions which have been analyzed through inlining. This is owned by
  /// AnalysisConsumer. It can be null.
  SetOfConstDecls *VisitedCallees;

  /// The flag, which specifies the mode of inlining for the engine.
  InliningModes HowToInline;

public:
  ExprEngine(cross_tu::CrossTranslationUnitContext &CTU, AnalysisManager &mgr,
             SetOfConstDecls *VisitedCalleesIn,
             FunctionSummariesTy *FS, InliningModes HowToInlineIn);

  virtual ~ExprEngine() = default;

  /// Returns true if there is still simulation state on the worklist.
  bool ExecuteWorkList(const StackFrame *SF, unsigned Steps = 150000) {
    assert(SF->inTopFrame());
    BR.setAnalysisEntryPoint(SF->getDecl());
    return Engine.ExecuteWorkList(SF, Steps, nullptr);
  }

  /// getContext - Return the ASTContext associated with this analysis.
  ASTContext &getContext() const { return AMgr.getASTContext(); }

  AnalysisManager &getAnalysisManager() { return AMgr; }
  const AnalysisManager &getAnalysisManager() const { return AMgr; }

  AnalysisDeclContextManager &getAnalysisDeclContextManager() {
    return AMgr.getAnalysisDeclContextManager();
  }

  CheckerManager &getCheckerManager() const {
    return *AMgr.getCheckerManager();
  }

  SValBuilder &getSValBuilder() { return svalBuilder; }
  const SValBuilder &getSValBuilder() const { return svalBuilder; }

  BugReporter &getBugReporter() { return BR; }
  const BugReporter &getBugReporter() const { return BR; }

  cross_tu::CrossTranslationUnitContext *
  getCrossTranslationUnitContext() {
    return &CTU;
  }

  // FIXME: Ideally the body of this method should look like
  //   CurrStackFrame = SF;
  //   CurrBlock = B;
  // where CurrStackFrame and CurrBlock are new member variables that
  // fulfill the roles of `currBldrCtx` in a more natural way.
  // This implementation is a temporary measure to allow a gradual transition.
  void setCurrStackFrameAndBlock(const StackFrame *SF, const CFGBlock *B) {
    // The current StackFrame and Block is reset at the beginning of
    // dispatchWorkItem. Ideally, this method should be called only once per
    // dispatchWorkItem call (= elementary analysis step); so the following
    // assertion is there to catch accidental repeated calls. If the current
    // StackFrame and Block needs to change in the middle of a single step
    // (which currently happens only once, in processCallExit), use an explicit
    // call to resetCurrStackFrameAndBlock.
    assert(!currBldrCtx && !OwnedCurrBldrCtx &&
           "The current StackFrame and Block is already set");
    OwnedCurrBldrCtx.emplace(Engine, B, SF);
    currBldrCtx = &*OwnedCurrBldrCtx;
  }

  void resetCurrStackFrameAndBlock() {
    currBldrCtx = nullptr;
    OwnedCurrBldrCtx = std::nullopt;
  }

  const NodeBuilderContext &getBuilderContext() const {
    assert(currBldrCtx);
    return *currBldrCtx;
  }

  const StackFrame *getRootStackFrame() const {
    assert(G.getRoot());
    return G.getRoot()->getLocation().getStackFrame();
  }

  /// Get the 'current' stack frame corresponding to the current work item
  /// (elementary analysis step handled by `dispatchWorkItem`).
  /// FIXME: This sometimes (e.g. in some `BeginFunction` callbacks) differs
  /// from the `StackFrame` that can be obtained from different sources
  /// (e.g. a recent `ExplodedNode`). Traditionally this stack frame is
  /// only used for block count calculations (`getNumVisited`); it is probably
  /// wise to follow this tradition until the discrepancies are resolved.
  const StackFrame *getCurrStackFrame() const {
    return currBldrCtx ? currBldrCtx->getStackFrame() : nullptr;
  }

  /// Get the 'current' CFGBlock corresponding to the current work item
  /// (elementary analysis step handled by `dispatchWorkItem`).
  const CFGBlock *getCurrBlock() const {
    return currBldrCtx ? currBldrCtx->getBlock() : nullptr;
  }

  ConstCFGElementRef getCFGElementRef() const {
    return {getCurrBlock(), currStmtIdx};
  }

  unsigned getNumVisited(const StackFrame *SF, const CFGBlock *Block) const {
    return Engine.WList->getBlockCounter().getNumVisited(SF,
                                                         Block->getBlockID());
  }

