class MemRegion : public llvm::FoldingSetNode {
public:
  enum Kind {
#define REGION(Id, Parent) Id ## Kind,
#define REGION_RANGE(Id, First, Last) BEGIN_##Id = First, END_##Id = Last,
#include "clang/StaticAnalyzer/Core/PathSensitive/Regions.def"
#undef REGION
#undef REGION_RANGE
  };

private:
  const Kind kind;
  mutable std::optional<RegionOffset> cachedOffset;

protected:
  MemRegion(Kind k) : kind(k) {}
  virtual ~MemRegion();

public:
  ASTContext &getContext() const;

  virtual void Profile(llvm::FoldingSetNodeID& ID) const = 0;

  virtual MemRegionManager &getMemRegionManager() const = 0;

  /// Deprecated. Gets the 'raw' memory space of a memory region's base region.
  /// If the MemRegion is originally associated with Unknown memspace, then the
  /// State may have a more accurate memspace for this region.
  /// Use getMemorySpace(ProgramStateRef) instead.
  [[nodiscard]] LLVM_ATTRIBUTE_RETURNS_NONNULL const MemSpaceRegion *
  getRawMemorySpace() const;

  /// Deprecated. Use getMemorySpace(ProgramStateRef) instead.
  template <class MemSpace>
  [[nodiscard]] const MemSpace *getRawMemorySpaceAs() const {
    return dyn_cast<MemSpace>(getRawMemorySpace());
  }

  /// Returns the most specific memory space for this memory region in the given
  /// ProgramStateRef. We may infer a more accurate memory space for unknown
  /// space regions and associate this in the State.
  [[nodiscard]] LLVM_ATTRIBUTE_RETURNS_NONNULL const MemSpaceRegion *
  getMemorySpace(ProgramStateRef State) const;

  template <class MemSpace>
  [[nodiscard]] const MemSpace *getMemorySpaceAs(ProgramStateRef State) const {
    return dyn_cast<MemSpace>(getMemorySpace(State));
  }

  template <typename... MemorySpaces>
  [[nodiscard]] bool hasMemorySpace(ProgramStateRef State) const {
    static_assert(sizeof...(MemorySpaces));
    return isa<MemorySpaces...>(getMemorySpace(State));
  }

  /// Set the dynamically deduced memory space of a MemRegion that currently has
  /// UnknownSpaceRegion. \p Space shouldn't be UnknownSpaceRegion.
  [[nodiscard]] ProgramStateRef
  setMemorySpace(ProgramStateRef State, const MemSpaceRegion *Space) const;

  LLVM_ATTRIBUTE_RETURNS_NONNULL const MemRegion *getBaseRegion() const;

  /// Recursively retrieve the region of the most derived class instance of
  /// regions of C++ base class instances.
  LLVM_ATTRIBUTE_RETURNS_NONNULL
  const MemRegion *getMostDerivedObjectRegion() const;

  /// Check if the region is a subregion of the given region.
  /// Each region is a subregion of itself.
  virtual bool isSubRegionOf(const MemRegion *R) const;

  LLVM_ATTRIBUTE_RETURNS_NONNULL
  const MemRegion *StripCasts(bool StripBaseAndDerivedCasts = true) const;

  /// If this is a symbolic region, returns the region. Otherwise,
  /// goes up the base chain looking for the first symbolic base region.
  /// It might return null.
  const SymbolicRegion *getSymbolicBase() const;

  /// Compute the offset within the top level memory object.
  RegionOffset getAsOffset() const;

  /// Get a string representation of a region for debug use.
  std::string getString() const;

  virtual void dumpToStream(raw_ostream &os) const;

  void dump() const;

  /// Returns true if this region can be printed in a user-friendly way.
  virtual bool canPrintPretty() const;

  /// Print the region for use in diagnostics.
  virtual void printPretty(raw_ostream &os) const;

  /// Returns true if this region's textual representation can be used
  /// as part of a larger expression.
  virtual bool canPrintPrettyAsExpr() const;

  /// Print the region as expression.
  ///
  /// When this region represents a subexpression, the method is for printing
  /// an expression containing it.
  virtual void printPrettyAsExpr(raw_ostream &os) const;

  Kind getKind() const { return kind; }

  StringRef getKindStr() const;

  template<typename RegionTy> const RegionTy* getAs() const;
  template <typename RegionTy>
  LLVM_ATTRIBUTE_RETURNS_NONNULL const RegionTy *castAs() const;

  virtual bool isBoundable() const { return false; }

  /// Get descriptive name for memory region. The name is obtained from
  /// the variable/field declaration retrieved from the memory region.
  /// Regions that point to an element of an array are returned as: "arr[0]".
  /// Regions that point to a struct are returned as: "st.var".
  /// Returns an empty string for regions that don't have a clear descriptive
  /// name (e.g. a heap are allocated by 'malloc').
  //
  /// \param UseQuotes Set if the name should be quoted.
  ///
  /// \param AllowFallback When true, always retursn a non-empty string, using
  /// vague descriptions like "the heap area", "the string literal" (or "the
  /// region" as a catch-all) when there is nothing better.
  ///
  /// \returns variable name for memory region
  std::string getDescriptiveName(bool UseQuotes = true,
                                 bool AllowFallback = false) const;

  /// Retrieve source range from memory region. The range retrieval
  /// is based on the decl obtained from the memory region.
  /// For a VarRegion the range of the base region is returned.
  /// For a FieldRegion the range of the field is returned.
  /// If no declaration is found, an empty source range is returned.
  /// The client is responsible for checking if the returned range is valid.
  ///
  /// \returns source range for declaration retrieved from memory region
  SourceRange sourceRange() const;
}

